/**
 * Zero Club navigation icons — Solar, linear when idle and solid when active.
 *
 * The tab bar needs the two-state behaviour a duotone glyph cannot give: an
 * outline that fills in when you are on that tab. So these are the same Solar
 * family as the rest of the app, drawn in two weights rather than one.
 *
 * Previously hand-drawn on their own grid, which is why the nav never quite
 * matched the screens it opened.
 *
 * Icons: Solar by 480 Design, CC BY 4.0.
 * Generated file — edit the generator, not this.
 */
import React from "react";

export interface ZeroIconProps {
  className?: string;
  active?: boolean;
}

function make(idle: string, solid: string) {
  return function NavIcon({ className, active }: ZeroIconProps) {
    return (
      <svg
        viewBox="0 0 24 24"
        className={className ? `zc-icon ${className}` : "zc-icon"}
        fill={active ? "currentColor" : "none"}
        aria-hidden="true"
        dangerouslySetInnerHTML={{ __html: active ? solid : idle }}
      />
    );
  };
}

